CREATE TABLE IF NOT EXISTS email_jobs (provider_message_id text PRIMARY KEY, status text NOT NULL DEFAULT 'pending', lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS messages_provider_unique ON messages(provider_message_id) WHERE provider_message_id IS NOT NULL; CREATE UNIQUE INDEX IF NOT EXISTS actions_source_unique ON proposed_actions(source_message_id) WHERE source_message_id IS NOT NULL; CREATE UNIQUE INDEX IF NOT EXISTS decisions_action_unique ON policy_decisions(proposed_action_id); CREATE TABLE IF NOT EXISTS action_executions (action_id uuid PRIMARY KEY REFERENCES proposed_actions(id), state text NOT NULL DEFAULT 'pending', lease_until timestamptz, provider_id text, last_error text, created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS app_settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
